Algorithm Products
  Dimension names[3] As String;
  Dimension prices[3] As Integer;
  For i <- 0 To 2 Do
    Read names[i];
    Read prices[i];
  EndFor
  For i <- 0 To 2 Do
    Write names[i], " ", prices[i];
  EndFor
EndAlgorithm

