evaluation.reference:
Record Product
  Define name As String;
  Define price, stock As Integer;
EndRecord

Algorithm Products
  Define products As Vector<Product> <- vector();
  Define name As String;
  Define price, stock As Integer;
  For i <- 1 To 3 Do
    Read name;
    Read price;
    Read stock;
    products.append(Product(name, price, stock));
  EndFor
  For Each product In products Do
    Write product.name, " ", product.price, " (", product.stock, " left)";
  EndFor
EndAlgorithm
